PYTHONPATH=. .venv/bin/python -c "
from pathlib import Path
from image_diff.dom.parse import load_snapshot
for name in ['before','after']:
    s = load_snapshot(Path('examples/general/synthetic_links_restyled/captures/%s_snapshot.json' % name))
    for e in s.elements:
        if e.selector.startswith('html:nth-child(1) > body:nth-child(2) > header:nth-child(1) > nav:nth-child(2) > a'):
            print(name, e.frames, e.own_text, e.box, e.styles.get('text-decoration-line'), e.styles.get('color'))
"
